require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';$pdo=Db::pdo();Security::start();$u=Security::requireRole(['reviewer','admin','super_admin']);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Indexation Health | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f6f8fb;color:#14213d;margin:0}main{max-width:1300px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px}.metric{font-size:28px;font-weight:800}.muted{color:#64748b}.bad{color:#b91c1c}.ok{color:#166534}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.toolbar button{border:0;border-radius:9px;padding:10px 13px;background:#123b67;color:#fff;cursor:pointer}.toolbar textarea{width:100%;min-height:120px}.table{overflow:auto}.row{display:grid;grid-template-columns:2.3fr .9fr .8fr .9fr .9fr 1.1fr;gap:8px;padding:10px 0;border-bottom:1px solid #eef2f7;align-items:start}.row.head{font-weight:700;font-size:12px;color:#64748b}.pill{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:11px}.attention{background:#fff7ed}.status-indexed{color:#166534}.status-crawled_not_indexed,.status-discovered_not_indexed{color:#b45309}.status-excluded_noindex,.status-not_found,.status-soft_404{color:#b91c1c}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:1.8fr 1fr 1fr}.hide-sm{display:none}}</style></head><body><main><h1>SEO & Indexation Health</h1><p class="muted">Operational view of strategic public URLs, sitemap coverage and known indexation states. Search Console data can be imported when connected; internal checks remain separate from actual Google index status.</p><div id="metrics" class="grid"></div><div class="toolbar"><button onclick="syncSitemap()">Sync sitemap coverage</button><button onclick="toggleImport()">Import index states</button><a href="/sitemap.xml" target="_blank">Open sitemap</a></div><div id="importBox" class="card" style="display:none"><h3>Import index states</h3><p class="muted">Paste JSON array with fields such as path, index_state, discovered_at, last_crawled_at, last_indexed_at, notes.</p><textarea id="importJson">[]</textarea><p><input id="source" value="manual_import" placeholder="source"> <button onclick="importStates()">Import</button></p></div><div class="card table"><div class="row head"><div>URL</div><div>Type</div><div>Sitemap</div><div>Index state</div><div class="hide-sm">Last indexed</div><div class="hide-sm">Attention</div></div><div id="rows"></div></div><p id="msg"></p></main><script>const csrf=<?=json_encode($csrf)?>;function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw new Error(d.error||'request_failed');return d}async function load(){try{let d=await api('/api/indexation-health');let s=d.summary||{};document.getElementById('metrics').innerHTML=[['Known',s.total],['Strategic',s.strategic],['In sitemap',s.in_sitemap],['Indexed',s.indexed],['Stuck',s.stuck],['Technical exclusions',s.technical_exclusions]].map(x=>`<div class="card"><div class="muted">${esc(x[0])}</div><div class="metric">${esc(x[1]??0)}</div></div>`).join('');document.getElementById('rows').innerHTML=(d.urls||[]).map(r=>`<div class="row ${r.attention?.needs_attention?'attention':''}"><div><strong>${esc(r.path)}</strong><br><span class="pill">${esc(r.priority_level)}</span></div><div>${esc(r.page_type)}</div><div>${r.sitemap_present?'✓':'Missing'}</div><div class="status-${esc(r.index_state)}">${esc(r.index_state)}</div><div class="hide-sm">${esc(r.last_indexed_at||'—')}</div><div class="hide-sm">${esc((r.attention?.reasons||[]).join(', ')||'—')}</div></div>`).join('')}catch(e){msg(e.message)}}async function syncSitemap(){try{let d=await api('/api/indexation-health/sync',{method:'POST',body:'{}'});msg(`Synced ${d.sitemap_url_count} sitemap URLs`,true);load()}catch(e){msg(e.message)}}function toggleImport(){let e=document.getElementById('importBox');e.style.display=e.style.display==='none'?'block':'none'}async function importStates(){try{let rows=JSON.parse(document.getElementById('importJson').value);let source=document.getElementById('source').value;let d=await api('/api/indexation-health/import',{method:'POST',body:JSON.stringify({rows,source})});msg(`Imported ${d.imported} states`,true);load()}catch(e){msg(e.message)}}function msg(t,ok=false){let e=document.getElementById('msg');e.textContent=t;e.style.color=ok?'#166534':'#b91c1c'}load();</script></body></html>